; King's Quest IV (SCI0), Korean UTF-8 translation. One map; the same faces in every
; render_target (1 bpp, hard-edged). The pairing selection (2026-10-15, step 1):
;   ui    - font 0 (status line, menu bar, parser line, system dialogs) and any other id:
;           SANGAM16.SVF, the 16 px san-1.0 GAM.KOR jamo set (SAN10.TXT), engine data
;           (also the engine's fallback face);
;   large - font 1 (large message boxes: parser replies, the "enter" prompt, inventory):
;           HWPHM24.SVF, HWP 1.x HANGUL1.PFT 24 px serif jamo set (HWP120.TXT);
;   msg   - font 4 (message boxes, narration, parser replies; the copy-protection and
;           first-run boxes): IYAGI16.SVF, san-1.0 Iyagi IYG.KOR 16 px jamo set;
;   dbg   - font 999 (debug): WCOMM16.SVF, han_wcomm.fnt of the iolo 6x2x1-fonts
;           collection (Wordcom), 16 px jamo set, ascent 15 (WCOMM.TXT).
; English is the game's own font on every id (range.basic-latin=original, game widths):
; the faces carry Hangul only, so "of Rosella", digits and punctuation are as in the
; English game. Font 1 sets size=24 and cell=glyph: the engine's default 16 px layout
; cell would draw 24 px glyphs off their pens, overlapping.
; Fallback: SANGAM16.SVF is the last face of every chain whose face lives in the jamo
; font pack, so a missing pack still shows Korean (16 px).
[map]
version=2

[render]
scale=2
blend=off

[fonts]
ui=SANGAM16.SVF
large=HWPHM24.SVF
msg=IYAGI16.SVF
dbg=WCOMM16.SVF
fb=SANGAM16.SVF

[font]
face=ui
missing=u+25a1
align=cell
range.basic-latin=original
advance.basic-latin=game

[font.1]
face=large,fb
size=24
cell=glyph

[font.4]
face=msg,fb

[font.999]
face=dbg,fb
